import java.util.concurrent.{ConcurrentHashMap, atomic}
import java.util.concurrent.atomic.{AtomicBoolean, AtomicLong, AtomicReference}
import sun.misc.{Signal, SignalHandler}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object InferenceServer {

  // Audit log buffer - append-only during normal operation
  private val auditBuffer = new mutable.ArrayBuffer[String](1024)
  private val bufferLock = new Object()
  private val requestCounter = new AtomicLong(0)
  private val shuttingDown = new AtomicBoolean(false)
  private val modelWeights = new AtomicReference[Array[Double]](null)
  private val pendingFlush = new AtomicBoolean(false)
  private val reloadRequested = new AtomicBoolean(false)

  // Model state tracking for safe shutdown
  private var activeInferences = 0
  private val inferenceLock = new Object()

  case class InferenceRequest(features: Array[Double], requestId: String)
  case class InferenceResult(prediction: Double, confidence: Double, requestId: String)

  // Sanitize user-controlled values before placing them in audit log entries
  // to prevent log injection / forged audit records (CWE-117).
  private def sanitizeForLog(value: String): String = {
    if (value == null) "<null>"
    else {
      val cleaned = value.replaceAll("[\\r\\n\\t\\x00-\\x1F\\x7F]", "_")
      if (cleaned.length > 256) cleaned.substring(0, 256) + "..." else cleaned
    }
  }

  def loadModel(path: String): Unit = {
    // Simulate loading model weights
    val weights = Array.fill(128)(scala.util.Random.nextGaussian())
    modelWeights.set(weights)
    auditLog(s"Model loaded from ${sanitizeForLog(path)} with ${weights.length} parameters")
  }

  def auditLog(message: String): Unit = {
    val timestamp = System.currentTimeMillis()
    val entry = s"[$timestamp] $message"
    bufferLock.synchronized {
      auditBuffer.append(entry)
      if (auditBuffer.size >= 512) {
        flushAuditBuffer()
      }
    }
  }

  private def flushAuditBuffer(): Unit = {
    // In production this writes to persistent storage
    if (pendingFlush.compareAndSet(false, true)) {
      try {
        val snapshot = auditBuffer.toArray
        auditBuffer.clear()
        // Simulate I/O write
        snapshot.foreach { entry =>
          System.err.println(s"AUDIT: $entry")
        }
      } finally {
        pendingFlush.set(false)
      }
    }
  }

  def runInference(request: InferenceRequest): Option[InferenceResult] = {
    if (shuttingDown.get()) return None

    inferenceLock.synchronized {
      activeInferences += 1
    }

    try {
      val weights = modelWeights.get()
      if (weights == null) {
        auditLog(s"Inference failed: model not loaded, reqId=${sanitizeForLog(request.requestId)}")
        return None
      }

      val reqNum = requestCounter.incrementAndGet()

      // Dot product inference
      val prediction = request.features.zip(weights).map { case (f, w) => f * w }.sum
      val sigmoid = 1.0 / (1.0 + math.exp(-prediction))
      val confidence = math.abs(sigmoid - 0.5) * 2.0

      val result = InferenceResult(sigmoid, confidence, request.requestId)
      auditLog(s"Inference #$reqNum completed: reqId=${sanitizeForLog(request.requestId)}, pred=${sigmoid}, conf=${confidence}")
      Some(result)
    } finally {
      inferenceLock.synchronized {
        activeInferences -= 1
        inferenceLock.notifyAll()
      }
    }
  }

  private def gracefulShutdown(): Unit = {
    shuttingDown.set(true)

    // Wait for active inferences to complete
    inferenceLock.synchronized {
      while (activeInferences > 0) {
        inferenceLock.wait(100)
      }
    }

    // Final audit flush
    auditLog("Server shutting down gracefully")
    flushAuditBuffer()
  }

  // Safe model reload - performed on dedicated thread, not in signal context
  private def performModelReload(): Unit = {
    // Acquire inference lock to ensure no concurrent inference uses stale weights
    inferenceLock.synchronized {
      while (activeInferences > 0) {
        inferenceLock.wait(50)
      }
      // All inferences quiesced - safe to swap
      val newWeights = Array.fill(128)(scala.util.Random.nextGaussian() * 0.01)
      modelWeights.set(newWeights)
      auditLog(s"Model reloaded with ${newWeights.length} parameters")
    }
  }

  // Signal handler for SIGUSR1 - only sets flag, no shared state mutation
  private val reloadHandler: SignalHandler = new SignalHandler {
    override def handle(sig: Signal): Unit = {
      // Signal-safe: only set atomic flag
      reloadRequested.set(true)
    }
  }

  // Signal handler for SIGTERM - only sets flag
  private val shutdownHandler: SignalHandler = new SignalHandler {
    override def handle(sig: Signal): Unit = {
      // Signal-safe: only set atomic flag
      shuttingDown.set(true)
    }
  }

  // Dedicated management thread processes signal flags safely
  private val managementThread = new Thread(new Runnable {
    override def run(): Unit = {
      while (!shuttingDown.get()) {
        if (reloadRequested.compareAndSet(true, false)) {
          auditLog("SIGUSR1 received - initiating safe model reload")
          performModelReload()
        }
        Thread.sleep(50)
      }
      // Perform graceful shutdown on management thread
      gracefulShutdown()
    }
  }, "mgmt-thread")

  def initialize(): Unit = {
    Signal.handle(new Signal("USR1"), reloadHandler)
    Signal.handle(new Signal("TERM"), shutdownHandler)
    loadModel("/models/default_v1.bin")
    managementThread.setDaemon(true)
    managementThread.start()
    auditLog("InferenceServer initialized")
  }

  def main(args: Array[String]): Unit = {
    initialize()

    // Simulate request processing loop
    val threads = (1 to 8).map { tid =>
      new Thread(new Runnable {
        override def run(): Unit = {
          var i = 0
          while (!shuttingDown.get()) {
            val features = Array.fill(128)(scala.util.Random.nextGaussian())
            val req = InferenceRequest(features, s"t${tid}-r${i}")
            runInference(req)
            i += 1
            Thread.sleep(1)
          }
        }
      })
    }

    threads.foreach(_.start())
    threads.foreach(_.join())
  }
}
